const classifyTaskDB=[{"w":"Sandel (2012)","gen":"Fuente","n":"La separación de las dos objeciones","g":"«What Money Can't Buy»","t":"Filosofía política contemporánea"},{"w":"Satz (2010)","gen":"Fuente","n":"Los cuatro parámetros","g":"«Why Some Things Should Not Be for Sale»","t":"La más operativa"},{"w":"Anderson (1993)","gen":"Fuente","n":"Los modos de valorar","g":"«Value in Ethics and Economics»","t":"La base filosófica"},{"w":"Titmuss (1970)","gen":"Fuente","n":"La sangre donada y la comprada","g":"«The Gift Relationship»","t":"Clásico fundador, y discutido"},{"w":"Arrow (1972)","gen":"Fuente","n":"La objeción a Titmuss","g":"«Gifts and Exchanges»","t":"Contracrítica obligada"},{"w":"Gneezy y Rustichini (2000)","gen":"Fuente","n":"La multa que subió los retrasos","g":"«A Fine is a Price»","t":"Experimento de campo"},{"w":"Lacetera, Macis y Slonim (2013)","gen":"Fuente","n":"Los incentivos que sí funcionaron","g":"En «Science»","t":"Disputa empírica viva"},{"w":"Roth (2007)","gen":"Fuente","n":"La repugnancia como restricción","g":"«Repugnance as a Constraint on Markets»","t":"Diseño de mercados, Nobel 2012"},{"w":"Brennan y Jaworski (2015)","gen":"Fuente","n":"Si se puede regalar, se puede vender","g":"«Markets Without Limits»","t":"El acero del bando contrario"},{"w":"Zelizer (1979)","gen":"Fuente","n":"El seguro de vida, de escándalo a rutina","g":"«Morals and Markets»","t":"Historia social"}];
