function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"En la fila del centro de salud, quien llega a las cuatro de la mañana consigue el primer turno y se lo vende por doscientos lempiras a quien llega a las siete con prisa. Los dos quedan mejor que antes y nadie fue obligado."},{"txt":"Una empresa ofrece reparar el techo de la escuela, que lleva años goteando, a cambio de poner su nombre en la fachada y repartir su publicidad en las aulas. El techo hace falta de verdad."},{"txt":"El vecino que echaba un ojo a la casa sin cobrar nada aceptó dinero por hacerlo, y desde entonces, si no se le paga, ya no lo hace."},{"txt":"En una conversación de patio alguien dice que vendería un riñón para salir de una deuda. Comprarlo está prohibido en casi todo el mundo, y en un país existe un sistema regulado con compensación donde no hay lista de espera."},{"txt":"El hospital pide reponer con donantes la sangre usada en una operación de la familia, y aparece alguien dispuesto a donar a cambio de dinero."},{"txt":"Una plataforma de estudio le paga puntos a quien lee, acierta y termina, y la casa que la escribió sospecha de ese mecanismo por lo que acaba de aprender en esta etapa."},{"txt":"Alguien propone cobrar entrada en el velorio de un vecino para ayudar a la familia con los gastos, en vez de pasar la colecta como siempre."},{"txt":"En un pueblo se ofrece dinero a las familias por aceptar en sus tierras una obra que nadie quiere cerca, y el apoyo a la obra baja en vez de subir."}];
const critCaseQuestions=["1. Describe el bien: quién vende, quién compra y qué cambia de manos de verdad.","2. Di cuál de las dos objeciones le cabe (justicia, corrupción, las dos o ninguna), y por qué. Si es de justicia, enciende los cuatro parámetros de Satz uno por uno.","3. Si alegas corrupción, muéstrala: qué se pierde exactamente, quién lo pierde y cómo se notaría. Nombra la fuente de esta etapa que sostiene tu lectura, con su etiqueta y su contracrítica al lado.","4. Escoge una de las cuatro salidas (permitir, permitir con reglas, sacar el dinero y diseñar otro mecanismo, o prohibir), calcula qué cuesta y a quién, contesta el acero de Brennan y Jaworski, y di qué te haría cambiar de opinión."];
const critCaseGuides=["Se empieza describiendo el bien como se describe un inventario: quién vende, quién compra y qué cambia de manos de verdad, que casi nunca es lo que parece a primera vista. En la fila no se vende un asiento: se vende el resultado de haber madrugado, y ahí ya está medio caso resuelto.","Después se pregunta cuál de las dos objeciones cabe, y se admite sin vergüenza cuando no cabe ninguna, que pasa más seguido de lo que la indignación permite ver. Si es de justicia, los cuatro parámetros de Satz se encienden uno por uno y por separado: vulnerabilidad, agencia débil, daño extremo a la persona y daño extremo a la sociedad. Encender uno solo no autoriza a prohibir; autoriza a atacar ese uno.","Si se alega corrupción, hay que mostrarla y no afirmarla: decir qué se pierde en concreto, quién lo pierde y cómo se notaría si de verdad se perdió. Esa es la parte que casi nadie escribe, y es la que separa un argumento de una costumbre. Y la fuente entra con su etiqueta y con su contracrítica al lado: Titmuss nunca va sin Arrow ni sin los experimentos de 2013, igual que Coase nunca va sin su advertencia de 1988.","Al final se escoge entre las cuatro salidas y no entre dos, que es lo que hace toda la diferencia: permitir, permitir con reglas, sacar el dinero y diseñar otro mecanismo (la salida de Roth), o prohibir. Se calcula la factura de la que se escoja, contando también a los que salen perdiendo si se prohíbe, porque prohibir sin resolver produce la versión clandestina, con los mismos daños y ninguna protección. Se contesta a Brennan y Jaworski en su mejor versión, y se cierra con el renglón que esta casa exige siempre: qué evidencia haría cambiar la decisión, con fecha."];

const critErrorBank=[{"txt":"\"Eso no se vende y punto\".","g1":"No dice cuál de las dos objeciones está usando, así que no hay nada que discutir ni nada que comprobar; la intuición puede ser correcta y aun así la frase no sirve para decidir nada.","g2":"La corrección nombra la objeción, muestra qué se pierde y escoge una de las cuatro salidas con su factura."},{"txt":"\"Todo lo que se vende se corrompe\".","g1":"Una regla que condena todo no selecciona nada, y una regla que no selecciona no es herramienta sino humor: casi todo lo que usamos se compra, empezando por el cuaderno donde se escribió la frase.","g2":"Se corrige diciendo qué bienes en concreto y por qué, con la pérdida mostrada caso por caso."},{"txt":"\"Si les incomoda, que se prohíba\".","g1":"Salta del asco a la prohibición sin pasar por el argumento, que es el modo de fallar propio de esta etapa; y el asco cambia con el siglo, como muestra la historia del seguro de vida.","g2":"Se corrige encendiendo los parámetros de Satz y escribiendo la factura de prohibir, con víctimas concretas."},{"txt":"\"Titmuss demostró que pagar arruina la donación\".","g1":"Es media cita: Arrow le objetó en 1972 y los experimentos de campo publicados en «Science» en 2013 encontraron que los incentivos aumentaron la donación de sangre.","g2":"Se corrige diciendo que la disputa está viva, mostrando los dos lados y anotando qué dato la resolvería."},{"txt":"\"El argumento de Brennan y Jaworski no vale la pena ni contestarlo\".","g1":"Es la regla del acero al revés: la tesis contraria entra en su mejor versión y se contesta, y quien la esquiva no defiende su posición, evita ponerla a prueba.","g2":"Se corrige reconstruyendo su argumento en su forma más fuerte antes de responderlo."},{"txt":"\"Prohibir no le hace daño a nadie\".","g1":"Prohibir tiene factura y a veces la paga una lista de espera: donde se prohíbe sin resolver aparece la versión clandestina, con los mismos daños y ninguna protección.","g2":"Se corrige escribiendo las dos facturas, la de permitir y la de prohibir, y comparándolas."}];

const critDecisionBank=["La casa va a escribir sobre la venta de turnos en la fila del centro de salud: ¿qué objeción se nombra primero, y qué salida se recomienda sin fingir que prohibir crea médicos?","Hay que explicarle a la familia por qué el favor del vecino se enfrió cuando se le pagó: ¿qué se dice exactamente, y qué NO se dice del vecino?","El caso del riñón entra al expediente: ¿cómo se escribe para que se enciendan los parámetros uno por uno, y qué se hace con el dato de que prohibir también deja muertos?","La escuela recibió la oferta del techo a cambio del nombre y la publicidad: ¿qué se recomienda, y qué factura se declara junto con la recomendación?","La disputa de la sangre va a la ficha: ¿se cita a Titmuss, a Arrow o a los experimentos de 2013, y qué dato haría falta para poder cerrarla?","La frase de Jael ya está escrita en el cuaderno: ¿se borra o se corrige, y con qué tres renglones se reescribe para que sirva para decidir algo?","Alguien quiere usar esta etapa para señalar a un funcionario con pleito abierto: ¿qué dice la regla de selección de la materia, y cómo se escribe el caso para que entre como categoría?","La casa se audita a sí misma por el XP que paga: ¿qué regla se impone, qué dice Fryer al respecto y qué señal haría cambiar el diseño?"];
const critDecisionGuide="La decisión correcta sigue siempre el mismo orden, y el orden es el método. Primero se describe el bien como se describe un inventario: quién vende, quién compra y qué cambia de manos de verdad, que casi nunca es lo que parece a primera vista, porque en la fila del centro de salud no se vende un asiento sino el resultado de haber madrugado. Después se pregunta cuál de las dos objeciones cabe, y se admite sin vergüenza cuando no cabe ninguna, que ocurre más seguido de lo que la indignación deja ver. Si la objeción es de justicia, se encienden los cuatro parámetros de Debra Satz uno por uno y por separado, porque encender uno solo no autoriza a prohibir sino a atacar ese uno: vulnerabilidad, agencia débil, daño extremo a la persona y daño extremo a la sociedad. Si la objeción es de corrupción, hay que mostrarla y no afirmarla, que es la parte que casi nadie escribe: qué se pierde exactamente, quién lo pierde y cómo se notaría si de verdad se perdió; sin eso lo que hay es una costumbre, y las costumbres cambian, como lo prueba la historia del seguro de vida que Zelizer documentó en 1979. Las fuentes entran con su etiqueta y con su contracrítica al lado, sin excepción y sin importar de qué lado caiga el resultado: Titmuss de 1970 nunca va sin Arrow de 1972 ni sin los experimentos publicados en Science en 2013, igual que en la etapa anterior Coase no iba sin su advertencia de 1988. Al final se escoge entre las cuatro salidas y no entre dos, que es lo que hace toda la diferencia: permitir, permitir con reglas, sacar el dinero y disenar otro mecanismo como hizo Roth con las cadenas de trasplante, o prohibir. Y se escribe la factura de la salida escogida, contando tambien a los que salen perdiendo si se prohibe, porque prohibir sin resolver produce la version clandestina con los mismos danos y ninguna proteccion, y a veces la cuenta se paga en lista de espera. Se contesta ademas el acero de Brennan y Jaworski en su mejor version, no en caricatura. Cuando el bien auditado es de la propia casa, la misma vara y el renglon de que evidencia haria cambiar la decision, con fecha.";

const critCompareBank=[{"a":"Escribir «vender turnos de la fila reparte por capacidad de pago lo que se repartía por madrugar».","b":"Escribir «vender turnos de la fila es una vergüenza».","ga":"Caso A: nombra la objeción y muestra qué cambia, así que de ahí salen las cuatro salidas con sus cuatro facturas y la conversación puede terminar en una decisión.","gb":"Caso B: describe un sentimiento verdadero y no propone nada; se puede repetir toda la vida sin que la fila cambie.","gr":"La diferencia no es de tono sino de uso: solo la primera se puede llevar a una reunión donde haya que decidir algo."},{"a":"Citar a Titmuss con Arrow y con los experimentos de 2013 al lado.","b":"Citar a Titmuss como si hubiera cerrado el asunto en 1970.","ga":"Caso A: deja la pregunta donde de verdad está, que es de qué depende el desplazamiento (el bien, el monto, la forma del pago), y eso se puede medir.","gb":"Caso B: usa a un autor como bandera y esconde medio siglo de discusión posterior, que es el vicio que esta materia enseña a cazar.","gr":"La regla no cambia según el tema: media cita es media cita, aunque la mitad ocultada sea la que a uno le estorba."},{"a":"Proponer citas por teléfono para que madrugar deje de ser la moneda de la fila.","b":"Proponer prohibir la venta de turnos y dar el asunto por resuelto.","ga":"Caso A: es la salida de diseño, ataca el mecanismo y no el síntoma, y viene con su costo declarado, que es montar y sostener el sistema de citas.","gb":"Caso B: prohíbe el intercambio y deja intacta la escasez que lo creó, así que la fila sigue igual y aparece la versión disimulada.","gr":"Entre vender y prohibir está diseñar, y esa tercera salida es la que casi nadie propone porque exige trabajo en vez de indignación."},{"a":"Decir «la objeción aquí es de justicia, y se ataca quitando la urgencia».","b":"Decir «la objeción aquí es de corrupción» sin poder decir qué se pierde.","ga":"Caso A: identifica una objeción que se puede desactivar, y por lo tanto abre una política concreta que se puede evaluar después.","gb":"Caso B: usa la objeción más fuerte sin pagar su precio, que es mostrar la pérdida; así queda una afirmación que no se puede comprobar ni refutar.","gr":"La objeción de corrupción es la más poderosa y por eso es la que más exige: quien la use sin mostrar la pérdida la está gastando."}];

const critCauseBank=[{"cause":"Se dice «eso no se vende» sin decir cuál de las dos objeciones es.","guide":"La frase no se puede usar para nada: no hay salida que se siga de ella, no hay factura que calcular y no hay manera de comprobar si el remedio funcionó. Y de paso enseña que en esta casa las palabras nuevas se usan como banderas, que es justo lo contrario de lo que la etapa quiere. La corrección cabe en una línea: nombrar la objeción, y si no cabe ninguna, decirlo."},{"cause":"Se alega corrupción y no se muestra qué se pierde.","guide":"Sin la pérdida mostrada no hay diferencia entre un argumento y una costumbre, y las costumbres cambian: el seguro de vida fue escandaloso y hoy no lo es, y esa historia la documentó Zelizer en 1979. Mostrar la pérdida obliga a decir quién la sufre y cómo se notaría, y esas dos preguntas suelen ordenar el caso entero."},{"cause":"Se prohíbe sin escribir la factura de prohibir.","guide":"Prohibir no hace desaparecer la necesidad que creó el mercado. Donde se prohíbe sin resolver aparece la versión clandestina, con los mismos daños y ninguna de las protecciones, y en algunos casos la factura se paga en lista de espera. Escribir esa factura no significa estar a favor de vender: significa estar dispuesto a mirar el costo de la propia posición."},{"cause":"Se cita a Titmuss sin Arrow y sin los experimentos posteriores.","guide":"Es exactamente la misma falta que citar a Coase sin su advertencia de 1988, y la casa la castiga igual aunque aquí la mitad ocultada sea la que le conviene a la conclusión bonita. La disputa sobre el desplazamiento de motivos está viva, se enseña viva, y quien la declare cerrada en cualquiera de las dos direcciones está vendiendo postura."},{"cause":"Se descarta el acero de Brennan y Jaworski porque incomoda.","guide":"La regla del acero, que esta ruta trajo del expediente gemelo, dice que la tesis contraria entra en su mejor versión. Aquí esa tesis es fuerte: si regalar un riñón es admirable, hay que explicar por qué venderlo sería un crimen. Quien no la conteste no ha terminado la etapa, y quien la caricaturice está haciendo lo que la materia entera enseña a no hacer."},{"cause":"Se usa la etapa para señalar a alguien con pleito abierto.","guide":"Rompe la regla de selección de la materia. Los conflictos vivos del patio entran como categoría y nunca como caso con nombre: se estudia qué hace el dinero con un voto o con una sentencia, y no se le pone la etiqueta a ninguna persona, a ningún partido ni a nadie en campaña. La herramienta sirve para pensar el mecanismo, no para ganar la discusión de esta semana."}];
const critEffectBank=[{"effect":"El caso de la fila entró al expediente con su objeción nombrada y su salida escogida.","guide":"Objeción de justicia, porque reparte por capacidad de pago lo que se repartía por madrugar; y también de corrupción, porque la fila era el único lugar donde el que tiene y el que no tiene valían igual. La salida escogida no es prohibir, porque prohibir no crea médicos, sino cambiar el mecanismo por citas, con su costo declarado: alguien tiene que montar y sostener ese sistema."},{"effect":"La casa pudo explicar por qué el favor del vecino se enfrió sin culpar al vecino.","guide":"Porque el pago no se sumó al favor: lo reemplazó. Antes era vecindad y se pagaba en vecindad; después fue un servicio y se paga en dinero. Es el mismo mecanismo que midieron Gneezy y Rustichini en 2000 y que Frey y Jegen ordenaron en 2001. Y el detalle que enseña la prudencia: quitar el pago no devuelve el favor, así que la pregunta hay que hacerla antes."},{"effect":"El caso del riñón quedó escrito con los cuatro parámetros encendidos uno por uno.","guide":"Vulnerabilidad encendida, porque la deuda es la que habla; agencia débil a medias, porque el riesgo a treinta años casi nadie lo entiende; daño extremo a la persona encendido, porque es irreversible; daño a la sociedad, discutible. Y con la otra mitad de la factura escrita: prohibir también deja muertos en lista de espera, y por eso la salida de diseño de Roth es la más seria de las cuatro."},{"effect":"La disputa de la sangre se enseñó viva, con los tres nombres y las tres etiquetas.","guide":"Titmuss (1970) como clásico fundador y discutido; Arrow (1972) como contracrítica obligada; y Lacetera, Macis y Slonim (2013) como disputa empírica viva. La casa no escogió bando: dijo de qué podría depender la diferencia, que es el bien, el monto, la forma del pago y si es anónimo o público, y anotó cuál sería el dato que la resolvería."},{"effect":"La escuela contestó a la empresa del techo sin quedarse con el techo goteando.","guide":"La objeción aquí es de corrupción y no de justicia, porque nadie estaba presionado: lo que se pierde es que el aula sea el único lugar donde a un niño no se le habla para venderle algo. Y la factura de decir que no se escribió con la misma letra: el techo sigue goteando. Por eso la respuesta no fue ni aceptar todo ni rechazar todo, sino la franja de en medio, que es donde viven casi todas las decisiones reales: una placa pequeña, sin publicidad en las aulas y por un plazo escrito."},{"effect":"La casa se auditó a sí misma por el XP que paga y dejó la regla por escrito.","guide":"El riesgo es real y tiene nombre: que el XP reemplace la curiosidad en vez de sumarse. Fryer (2011) encontró que pagar por insumos funciona mejor que pagar por resultados, y por eso esta casa paga sobre todo por hacer. Las preguntas de análisis de las lecturas van sin XP a propósito. Y la señal que obligaría a cambiar el diseño está escrita: que alguien deje de leer el día que ya no dan puntos."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🩸 El bien sobre la mesa · Forma ${cf} · Lo que el dinero no debe comprar · Ruta del Expediente Dorado`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El bien sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Cuál de las dos objeciones le cabe a este bien, y qué se pierde exactamente si se vende? Nombra la fuente con su etiqueta y su contracrítica al lado, escoge una de las cuatro salidas, y calcula qué cuesta esa salida y a quién, contando también a los que pierden si se prohíbe.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos se puede llevar a una reunión donde haya que decidir, y cuál solo se puede repetir? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El bien sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El bien sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Cuál de las dos objeciones le cabe a este bien, y qué se pierde exactamente si se vende? Nombra la fuente con su etiqueta y su contracrítica al lado, escoge una de las cuatro salidas, y calcula qué cuesta esa salida y a quién, contando también a los que pierden si se prohíbe.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se puede llevar a una reunión donde haya que decidir, y cuál solo se puede repetir? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El bien sobre la mesa Lo que el dinero no debe comprar · Ruta del Expediente Dorado · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #4c1d95;background:#f5f3ff;color:#4c1d95;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#4c1d95;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #4c1d95;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#f5f3ff;border-left:3px solid #4c1d95;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#f5f3ff;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#f5f3ff;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#4c1d95;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #4c1d95;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El bien sobre la mesa · Lo que el dinero no debe comprar · Ruta del Expediente Dorado · Etapa 3 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El bien sobre la mesa · Lo que el dinero no debe comprar · Ruta del Expediente Dorado · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1970","icon":"🩸","label":"Titmuss y el regalo","text":"En <strong>«The Gift Relationship»</strong>, Richard Titmuss compara la sangre donada con la comprada y sostiene que <strong>pagar reduce y empeora la donación</strong>. Etiqueta: <strong>clásico fundador, y discutido</strong>. Es el texto con el que empieza toda esta conversación."},{"y":"1972","icon":"✋","label":"Arrow contesta","text":"En <strong>«Gifts and Exchanges»</strong>, <strong>Kenneth Arrow</strong> le objeta a Titmuss que <strong>de esos datos no se sigue esa conclusión moral</strong>. Etiqueta: <strong>la contracrítica obligada</strong>, y de un premio Nobel. Desde aquí, Titmuss no se cita nunca solo."},{"y":"1979","icon":"📜","label":"Zelizer y el asco que cambia","text":"En <strong>«Morals and Markets»</strong>, <strong>Viviana Zelizer</strong> documenta cómo el <strong>seguro de vida</strong> pasó de escandaloso a normal. Etiqueta: <strong>historia social</strong>. Es la prueba de que la repugnancia se mueve con el siglo, y por eso no basta como argumento."},{"y":"1993","icon":"📚","label":"Anderson y los modos de valorar","text":"En <strong>«Value in Ethics and Economics»</strong>, <strong>Elizabeth Anderson</strong> muestra que <strong>valorar no es un verbo único</strong>: se usa una herramienta, se respeta a una persona, se venera un símbolo. Etiqueta: <strong>la base filosófica</strong> de la objeción de corrupción."},{"y":"2000","icon":"⏰","label":"La multa que salió al revés","text":"<strong>Uri Gneezy y Aldo Rustichini</strong> publican <strong>«A Fine is a Price»</strong>: unas guarderías multan a los padres impuntuales y <strong>los retrasos suben</strong>; al quitar la multa, no vuelven a bajar. Etiqueta: <strong>experimento de campo</strong>, y el más citado de la etapa."},{"y":"2007","icon":"🧩","label":"Roth y la repugnancia","text":"En <strong>«Repugnance as a Constraint on Markets»</strong>, <strong>Alvin Roth</strong> trata el asco como <strong>una restricción del terreno</strong> y no como un error. De ahí sale la salida de diseño: cambiar el mecanismo en vez de discutir el precio. <strong>Nobel en 2012</strong>, con Lloyd Shapley."},{"y":"2010","icon":"📐","label":"Satz y los cuatro parámetros","text":"En <strong>«Why Some Things Should Not Be for Sale»</strong>, <strong>Debra Satz</strong> da <strong>cuatro parámetros que se encienden por separado</strong>: vulnerabilidad, agencia débil, daño extremo a la persona y daño extremo a la sociedad. Etiqueta: <strong>la más operativa</strong> de todas."},{"y":"2012","icon":"⚖️","label":"Sandel separa las dos","text":"En <strong>«What Money Can't Buy»</strong>, <strong>Michael Sandel</strong> separa <strong>la objeción de justicia de la de corrupción</strong>, y con eso la discusión se puede tener sin gritar. Etiqueta: <strong>filosofía política contemporánea</strong>. Es la columna vertebral de esta etapa."},{"y":"2013","icon":"🧪","label":"El dato que descoloca","text":"En <strong>«Science»</strong>, <strong>Lacetera, Macis y Slonim</strong> publican experimentos de campo grandes donde <strong>los incentivos sí aumentaron la donación de sangre</strong>. Etiqueta: <strong>disputa empírica viva</strong>. La casa lo pone aunque desordene la conclusión bonita."},{"y":"2015","icon":"🔩","label":"El acero del otro lado","text":"En <strong>«Markets Without Limits»</strong>, <strong>Jason Brennan y Peter Jaworski</strong> sostienen que <strong>si algo puede regalarse, puede venderse</strong>, y que lo reprobable está en el acto y no en el pago. Etiqueta: <strong>el acero del bando contrario</strong>. Se contesta, no se esquiva."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(prueba){sfx(prueba?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(prueba){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🩸</span><span class="ms-text"><strong>Quedó anotado lo que de verdad pasó:</strong> «el precio no se sumó al motivo, lo reemplazó: mientras llegar tarde era una falta de consideración, uno se apuraba por vergüenza; cuando pasó a costar, uno paga y llega tranquilo».</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧾</span><span class="ms-text"><strong>Y debajo, lo que se sigue de ahí:</strong> antes de poner precio a algo hay que preguntar <strong>qué se estaba haciendo ahí sin precio</strong>, porque la operación no siempre es reversible. <strong>Gneezy y Rustichini (2000) y Frey y Jegen (2001)</strong> entran con su etiqueta, y al lado entra el dato incómodo: <strong>en 2013 los incentivos sí aumentaron la donación de sangre</strong>, así que esto no es una maldición automática.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">💸</span><span class="ms-text"><strong>Quedó una regla falsa:</strong> «con multa la gente se porta bien». Funciona en muchísimos casos, suena a sentido común, y por eso mismo es peligrosa: nadie la va a revisar.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega en dos partes:</strong> con esa regla no se puede explicar por qué los retrasos subieron, ni por qué al quitar la multa no volvieron a bajar; y de camino queda enseñado que aquí los datos que estorban se ignoran. Se tacha y se reescribe con el mecanismo: <strong>el precio a veces reemplaza el motivo, y esa operación no siempre se puede deshacer.</strong></span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"justicia":{"nombre":"La objeción de justicia","icon":"⚖️","estructura":{"title":"Qué dice","info":"• Que <strong>el trato no fue libre de verdad</strong>, porque una parte entró con la urgencia encima<br>• No objeta el bien: objeta <strong>las condiciones en que se firmó</strong><br>• Y por eso <strong>se cae sola si esas condiciones mejoran</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se encienden los <strong>cuatro parámetros de Satz</strong>, uno por uno y por separado<br>• Vulnerabilidad, agencia débil, daño extremo a la persona, daño extremo a la sociedad<br>• Y se pregunta <strong>quién de los dos podía esperar</strong>, que casi siempre resuelve el caso"},"enfermedades":{"title":"Dónde se cae","info":"• Encender <strong>un solo parámetro y pedir prohibición</strong>, cuando lo que toca es atacar ese uno<br>• Confundirla con la de corrupción y responderla con datos que no vienen al caso<br>• Y olvidar que <strong>prohibir no quita la urgencia</strong>: la deja igual y sin salida"},"cuidados":{"title":"En esta casa","info":"• <strong>Satz (2010)</strong> se usa como instrumento, no como lista de prohibiciones<br>• Con <strong>Anderson (1993)</strong> detrás, que puso la base de por qué hay modos distintos de valorar<br>• Y los pleitos vivos del patio entran <strong>como categoría, no con nombre propio</strong>"}},"corrupcion":{"nombre":"La objeción de corrupción","icon":"🩸","estructura":{"title":"Qué dice","info":"• Que <strong>el precio degrada el bien</strong>, aunque el trato sea libre y entre iguales<br>• No que salga peor: que <strong>ya no es la misma cosa</strong><br>• Y si vale, <strong>vale siempre</strong>, porque no depende de las condiciones"},"funcion":{"title":"Cómo se reconoce","info":"• Se pregunta <strong>qué era ese bien cuando se daba</strong> y qué queda cuando se compra<br>• La disculpa, el premio de honor, el turno de la fila, la amistad<br>• Y se exige la prueba: <strong>qué se pierde, quién lo pierde y cómo se notaría</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• <strong>Afirmarla en vez de mostrarla</strong>, que es el error más común de la etapa<br>• Usarla para todo, con lo cual <strong>deja de seleccionar nada</strong><br>• Y confundir una <strong>costumbre</strong> con una pérdida: las costumbres cambian, y hay historia que lo prueba"},"cuidados":{"title":"En esta casa","info":"• <strong>Sandel (2012)</strong> entra siempre con <strong>Brennan y Jaworski (2015)</strong> al lado<br>• Y con <strong>Zelizer (1979)</strong>, que recuerda que el seguro de vida también fue escandaloso<br>• La prueba de la pérdida <strong>se escribe, no se supone</strong>"}},"motivos":{"nombre":"El desplazamiento de motivos","icon":"🧪","estructura":{"title":"Qué dice","info":"• Que <strong>el precio no se suma al motivo anterior: a veces lo reemplaza</strong><br>• Y que la operación <strong>no siempre es reversible</strong>: quitar el pago no devuelve el motivo<br>• Ordenado como teoría por <strong>Frey y Jegen (2001)</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se pregunta antes de poner precio: <strong>¿esto ya se estaba haciendo por otro motivo?</strong><br>• La multa de la guardería, el pueblo suizo, el favor del vecino<br>• Y se mira si al pagar <strong>la conducta empeoró en vez de mejorar</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Tomarlo por <strong>ley automática</strong>: en 2013 los incentivos sí aumentaron la donación de sangre<br>• Citar a <strong>Titmuss sin Arrow</strong>, que es media cita y la casa la castiga igual<br>• Y olvidar que depende del <strong>bien, del monto y de la forma del pago</strong>"},"cuidados":{"title":"En esta casa","info":"• <strong>Titmuss (1970), Arrow (1972) y los experimentos de 2013</strong> se citan juntos, siempre<br>• La casa se aplica el hallazgo a sí misma: <strong>el XP y lo que dice Fryer (2011)</strong><br>• Y la disputa <strong>se enseña viva</strong>, con el dato que la resolvería anotado"}},"diseno":{"nombre":"La repugnancia y el diseño","icon":"🧩","estructura":{"title":"Qué dice","info":"• Que el asco de la gente es <strong>una restricción real del terreno</strong>, no un error a corregir<br>• Que <strong>cambia con el tiempo</strong>, y por eso no basta como argumento<br>• Pero que es <strong>terca</strong>, y un diseño que la ignore no se aplica nunca"},"funcion":{"title":"Cómo se reconoce","info":"• Se busca <strong>dónde estaba el problema de verdad</strong>, que casi nunca es el precio<br>• En los riñones era <strong>de emparejamiento</strong>, y por eso hubo cadenas de trasplante<br>• Y se abre la tercera salida: <strong>sacar el dinero y diseñar otro mecanismo</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Quedarse en <strong>los dos botones</strong> de la discusión pública: vender o prohibir<br>• Usar el asco <strong>como prueba</strong>, cuando la historia enseña que se mueve<br>• Y proponer un diseño <strong>sin decir lo que cuesta montarlo y sostenerlo</strong>"},"cuidados":{"title":"En esta casa","info":"• <strong>Roth (2007)</strong> entra con su <strong>Nobel de 2012</strong> y con lo que construyó, no solo con lo que dijo<br>• Las salidas son <strong>cuatro y no dos</strong>, y eso se repite hasta que se vuelva reflejo<br>• Y toda salida se escribe <strong>con su factura</strong>, porque ninguna regla es gratis"}}};
let labParte='justicia',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== PREGUNTAS DE LAS LECTURAS =====================
// Tres baterías sobre los cinco textos: comprensión lectora (25), completar
// (10) y análisis complejo (10). Los bancos se escriben desde
