const lectComprensionBank=[{"t":"Borges","q":"¿Qué oficio tenía el tío del narrador, y qué sostenía?","o":["a) Era rematador, y sostenía que no existe objeto que no encuentre comprador","b) Era notario, y sostenía que todo contrato es válido","c) Era médico, y sostenía que la salud no tiene precio","d) Era librero, y sostenía que los libros no se venden"],"c":0},{"t":"Borges","q":"Al segundo año de su catálogo, ¿qué descubrió el narrador con alarma?","o":["a) Que su tío había muerto","b) Que el catálogo se había perdido","c) Que todas las palabras de su lista figuraban en avisos clasificados","d) Que nadie quería leerlo"],"c":2},{"t":"Borges","q":"¿Qué trabajo de Alvin Roth encontró en la biblioteca, y de qué año?","o":["a) «The Gift Relationship», de 1970","b) «Markets Without Limits», de 2015","c) «Morals and Markets», de 1979","d) «Repugnance as a Constraint on Markets», de 2007"],"c":3},{"t":"Borges","q":"¿Cuál es la asimetría que el narrador anota al margen como la más honda?","o":["a) Que la de corrupción es más fácil de probar","b) Que ninguna de las dos objeciones sirve","c) Que las dos se caen con el tiempo","d) Que la objeción de justicia puede desaparecer si mejora el mundo, y la de corrupción, si es verdadera, lo es para siempre"],"c":3},{"t":"Borges","q":"¿Cuál fue la última entrada que el narrador agregó al catálogo?","o":["a) El nombre de su tío","b) La lista de los objetos vendidos","c) Una cita inventada","d) Una objeción contra sí mismo, tomada de Brennan y Jaworski"],"c":3},{"t":"Cervantes","q":"¿A cuánto se convino primero el precio por azote, y a cuánto lo subió Sancho?","o":["a) A un real, y lo subió a un ducado","b) A dos maravedís, y no lo subió","c) A cuartillo, y lo subió a real","d) No hubo precio: fue gratis"],"c":2},{"t":"Cervantes","q":"¿Dónde descargó Sancho los azotes que había vendido?","o":["a) En los troncos de las hayas","b) En sus propias espaldas","c) En el jumento","d) En el aire, sin tocar nada"],"c":0},{"t":"Cervantes","q":"Según don Quijote, ¿qué compró él con su dinero y qué se quedó sin comprar?","o":["a) Compró la obra y se quedó sin la voluntad, que es lo que más le importaba","b) No compró nada de nada","c) Compró la voluntad y perdió la obra","d) Compró las hayas"],"c":0},{"t":"Cervantes","q":"En la escena de la venta, ¿quiénes son los quejosos según don Quijote?","o":["a) El caminante que compró el lugar","b) Los que no hablaron, como la mujer del niño que madrugó y quedó última","c) El primero de la fila, que vendió su lugar","d) El cirujano que sacaba muelas"],"c":1},{"t":"Cervantes","q":"¿Qué remedio propone Sancho para la fila, y qué le advierte don Quijote?","o":["a) Prohibir la venta; y le advierte que está bien así","b) Pagar más caro; y le advierte que es lo justo","c) Cédulas con la hora escrita; y le advierte que también cuesta, y que ese costo lo paga alguien","d) Que todos madruguen; y no le advierte nada"],"c":2},{"t":"Harari","q":"¿Qué ejemplo usa el ensayo para mostrar que el asco cambia con el tiempo?","o":["a) La compra de votos","b) El seguro de vida, cuya historia documentó Viviana Zelizer en 1979","c) La donación de sangre","d) Las cadenas de trasplante"],"c":1},{"t":"Harari","q":"¿Cuál de los cuatro parámetros de Satz explica que casi todas las sociedades prohíban comprar votos y sentencias?","o":["a) La vulnerabilidad","b) La agencia débil","c) El cuarto: el daño que alcanza a quienes no participaron","d) El daño extremo a la persona"],"c":2},{"t":"Harari","q":"Según el ensayo, ¿qué pasó cuando las guarderías quitaron la multa?","o":["a) Los retrasos desaparecieron","b) Los retrasos no volvieron a bajar","c) Los padres pagaron el doble","d) Las guarderías cerraron"],"c":1},{"t":"Harari","q":"¿Qué encontró Roland Fryer en 2011 al pagar a estudiantes?","o":["a) Que pagar por leer libros funcionó bastante mejor que pagar por sacar buenas notas","b) Que ningún pago funciona","c) Que pagar por notas fue lo más eficaz","d) Que los estudiantes devolvieron el dinero"],"c":0},{"t":"Harari","q":"¿Qué dos datos legales pone el ensayo uno al lado del otro, y por qué?","o":["a) Dos leyes del mismo país, para mostrar que se contradicen","b) La ley estadounidense de 1984 que prohíbe comprar órganos y el sistema regulado que existe en Irán desde 1988, porque cada uno incomoda a un lado distinto","c) Ninguno: el ensayo no cita leyes","d) Dos tratados internacionales, para mostrar que todos prohíben lo mismo"],"c":1},{"t":"Entrevista","q":"¿Qué contesta Sandel cuando Sanchís le pregunta qué no compraría jamás?","o":["a) Un riñón y una casa","b) Una disculpa y un premio, porque al comprarlos dejan de existir y se convierten en otra cosa","c) Nada: dice que todo puede comprarse","d) Un libro dedicado"],"c":1},{"t":"Entrevista","q":"¿Qué ejemplo pequeño pone Sandel sobre la fila?","o":["a) La fila del pan en su barrio de Minneapolis","b) La fila de su propio curso en Harvard","c) Los conciertos con reventa de boletos","d) Las empresas de Washington que pagan a gente por hacer fila y venden el puesto para las audiencias públicas del Congreso"],"c":3},{"t":"Entrevista","q":"Según Sandel, ¿qué es lo único que distingue una convicción de una mercancía?","o":["a) La honradez con el dato adverso: decir uno mismo la evidencia que le quita la razón, como la de «Science» en 2013","b) El número de seguidores que tenga","c) Que la convicción sea antigua","d) Que la diga un filósofo y no un economista"],"c":0},{"t":"Entrevista","q":"¿Qué le quita el sueño a Sandel?","o":["a) Que se prohíban demasiados mercados","b) Que los estudiantes no lean","c) La desigualdad en una sociedad de mercado: cuando el dinero compra el turno, la escuela y la influencia, cuantas más cosas están en venta, más cuesta ser pobre","d) Que la filosofía pierda audiencia"],"c":2},{"t":"Entrevista","q":"¿Cuándo dice Sandel que es feliz, y por qué esa respuesta cierra la entrevista?","o":["a) Cuando termina un libro, porque puede descansar","b) Cuando llena el teatro Sanders, porque mide su éxito","c) Cuando viaja a Oxford, donde estudió","d) Cuando un estudiante le cambia de opinión: ese momento comprado no ocurriría, y es su ejemplo favorito de todo lo dicho"],"c":3},{"t":"Quintero y Gala","q":"Según Gala, ¿qué compraron los padres de la guardería con la multa?","o":["a) Más horas de guardería","b) La buena voluntad de las maestras","c) El derecho a no avergonzarse, y al retirar la multa la vergüenza ya no volvió, como una flor que no se puede replantar","d) Tiempo para trabajar"],"c":2},{"t":"Quintero y Gala","q":"¿Por qué dice Gala que su perro Troylo era compañía y no servicio?","o":["a) Porque no se le habría ido con otro ni por todo el jamón de la sierra: con él hizo un libro en 1981, y esa lealtad no estaba en venta","b) Porque le costó muy caro","c) Porque estaba adiestrado para acompañar","d) Porque se lo regaló un amigo"],"c":0},{"t":"Quintero y Gala","q":"En la fila del hospital, ¿quién pierde según Gala cuando uno vende su turno?","o":["a) El que compró, porque pagó de más","b) La fila entera: era de los últimos sitios donde el rico y el pobre pesaban lo mismo, y el negocio lo pagan los que no firmaron","c) El médico, que atiende desordenado","d) Nadie: los dos ganan"],"c":1},{"t":"Quintero y Gala","q":"¿Qué imagen usa Gala para el que prohíbe sin arreglar?","o":["a) El que riega un rosal seco","b) El que apaga la lámpara sin tocar la flor","c) El que despide a un criado excelente","d) El que cierra la ventana y se deja el humo dentro: la casa queda muy decente y los de adentro tosiendo"],"c":3},{"t":"Quintero y Gala","q":"¿Cómo cierra Gala la conversación?","o":["a) Recitando a Séneca de memoria","b) Con un silencio y un aforismo: lo que vale de verdad no tiene precio sino cuidado, y el cuidado no se paga, se tiene","c) Pidiendo que se prohíba vender turnos","d) Despidiéndose sin contestar la última pregunta"],"c":1}];
// La etiqueta `t` de cada oración dice EN QUÉ TEXTOS se encuentra el dato,
// porque se contesta con la lectura delante. Aquí no vale un «las cinco»
// genérico: el capítulo cervantino no cita estudios modernos (sería un
// anacronismo en su voz), y Satz solo aparece en el cuento, el ensayo y la
// entrevista, no en la conversación de Quintero y Gala. La etiqueta se
// escribe veraz por entrada, no bonita por costumbre.
const lectCompletarBank=[{"t":"Borges, Harari y las dos entrevistas","q":"Richard Titmuss publicó «The Gift Relationship» en ___.","a":"1970"},{"t":"Borges, Harari y las dos entrevistas","q":"Kenneth Arrow le respondió en «Gifts and Exchanges», de ___.","a":"1972"},{"t":"Borges","q":"Alvin Roth escribió «Repugnance as a Constraint on Markets» en ___.","a":"2007"},{"t":"Borges, Harari y las dos entrevistas","q":"Michael Sandel separó las dos objeciones en «What Money Can't Buy», de ___.","a":"2012"},{"t":"Borges, Harari y la entrevista","q":"Debra Satz publicó «Why Some Things Should Not Be for Sale» en ___.","a":"2010"},{"t":"Harari","q":"Gneezy y Rustichini publicaron «A Fine is a Price» en ___.","a":"2000"},{"t":"Harari","q":"Viviana Zelizer documentó la historia del seguro de vida en «Morals and Markets», de ___.","a":"1979"},{"t":"Borges","q":"Brennan y Jaworski publicaron «Markets Without Limits» en ___.","a":"2015"},{"t":"Cervantes","q":"Sancho descargó los azotes que había vendido en los troncos de las ___.","a":"hayas"},{"t":"Cervantes","q":"Don Quijote dijo que compró la obra y se quedó sin la ___.","a":"voluntad"}];
const lectAnalisisBank=[{"q":"1. Las tres primeras lecturas llegan al mismo límite por tres puertas. Explica qué hace cada una de esas voces que las otras dos no pueden hacer, y qué se perdería leyendo solo una.","guia":"El cuento convierte el límite en una manía personal y por eso lo vuelve memorable: un hombre pasa la vida armando el catálogo de lo invendible y descubre que su lista no era de imposibles sino de incomodidades, que varían con la latitud y con el siglo. Esa forma enseña algo que un manual no puede: que el asco es un dato y no una prueba. El capítulo lo vuelve escena, risa y refrán, y con eso llega a donde el argumento no llega: los azotes vendidos a real, las hayas maltratadas sin culpa y la fila del sacamuelas dejan la lección pegada al cuerpo, y el refrán final la deja en dos renglones que cualquiera se puede repetir. El ensayo pone la escala de especie y ordena la erudición: separa las dos objeciones, encadena los estudios con sus años y obliga a mirar la factura de prohibir. Leyendo solo el cuento se tendría melancolía sin instrumento; solo el capítulo, sabiduría sin fuentes; solo el ensayo, fuentes sin ninguna imagen que las sostenga en la memoria. Las tres juntas dan lo mismo por tres caminos, y por eso la casa las escribe así."},{"q":"2. El narrador del cuento dice que su catálogo «dejó de ser una lista y se volvió un formulario». Explica qué significa eso y por qué es exactamente lo que esta etapa quiere enseñar.","guia":"Una lista dice qué está prohibido y no dice por qué, de modo que no sirve para ningún caso nuevo: si aparece un bien que la lista no contempla, hay que inventar la respuesta de cero o copiar la costumbre. Un formulario es otra cosa: son preguntas que se aplican a cualquier caso y que obligan a decir dónde está el problema. Por eso el narrador cambia su lista por los cuatro parámetros de Satz, que se encienden por separado, y por la distinción de Sandel entre las dos objeciones. Eso es exactamente la vara de la etapa: no se pide una opinión sobre los riñones o sobre la fila, se pide llenar la hoja del bien, que es un formulario de cinco renglones. Y hay una ganancia extra que el cuento hace notar sin decirlo: un formulario se puede discutir con alguien que piense distinto, porque los dos pueden señalar en qué renglón discrepan. Con una lista de invendibles solo se puede coincidir o pelear."},{"q":"3. Don Quijote dice que compró la obra y se quedó sin la voluntad, y que en el trato salió perdiendo aunque las cuentas digan que ganó. Explica esa frase con el vocabulario de la etapa.","guia":"Es la objeción de corrupción dicha en cervantino, y dicha mejor que en muchos manuales. Lo que don Quijote quería no era que unos azotes ocurrieran: era que Sancho quisiera darlos, porque el valor de la penitencia estaba en la voluntad de quien la hacía. Al poner precio compró la conducta y expulsó el motivo, que es exactamente el desplazamiento de motivos que midieron Gneezy y Rustichini en 2000 y que Frey y Jegen ordenaron como teoría en 2001. Las cuentas dicen que ganó porque recibió lo que pagó, y esa contabilidad es correcta en su propio idioma: hubo un intercambio voluntario y las dos partes lo aceptaron. Lo que la contabilidad no registra es que el bien cambió de naturaleza en el camino. El remate del capítulo lo lleva al extremo cómico y perfecto: Sancho ni siquiera entregó la obra, se la dio a las hayas, de modo que el dinero terminó comprando solamente el ruido. Quien paga por lo que solo la voluntad puede dar compra la apariencia, y encima se queda tan satisfecho que ya no busca la cosa."},{"q":"4. En la escena de la venta, don Quijote dice que los quejosos son los que no hablaron. Explica por qué esa frase es el argumento contra la venta de turnos, y qué objeción está usando.","guia":"Está usando las dos, y por eso la escena es útil. La de justicia salta a la vista: la mujer del niño madrugó y quedó última, de modo que el reparto pasó de premiar el madrugón a premiar la bolsa, y ella no podía competir en esa moneda. La de corrupción es la que la frase señala con más finura: mientras la fila se ganaba madrugando, era el único lugar donde el rico y el pobre valían lo mismo por una vez, y eso no era un efecto secundario sino parte de lo que la fila era. Al comprarse, la fila se vuelve un bien más, repartido como todos los demás. Y el hallazgo del argumento es de método: el intercambio que se ve fue voluntario y dejó contentos a los dos que hablaron, así que quien mire solo a las partes que firman va a concluir que todo mejoró. El daño está en los que no participaron, que es también el cuarto parámetro de Satz, el más raro y el más grave. Por eso la frase vale como regla general: ante cualquier trato, hay que preguntar a quién le cambió la vida sin haber firmado nada."},{"q":"5. El ensayo insiste en que «el asco cambia». Explica qué hace esa afirmación con la posición de quien quiere prohibir, y por qué no la destruye.","guia":"La debilita en un punto concreto y la obliga a mejorar. Si el único fundamento para decir que algo no debe venderse es que repugna, la historia deja mal parado ese fundamento: prestar con interés fue pecado, el seguro de vida pareció indecente y hoy se contrata sin pensarlo, y esa mudanza la documentó Viviana Zelizer en 1979. Quien apoye su prohibición solo en el asco está apoyándola en algo que se mueve con el siglo. Pero no la destruye por dos razones. La primera es que el sentimiento suele señalar dónde mirar, y casi siempre acierta en el sitio aunque no en el argumento: el asco frente a la venta de riñones apunta a la vulnerabilidad y a la irreversibilidad, que son parámetros reales. La segunda la aporta Roth en 2007: aunque el asco cambie, mientras exista es una restricción del terreno, y un diseño que lo ignore no se va a aplicar nunca por bueno que sea en el papel. De modo que el asco no es una prueba, pero sí es un dato con el que hay que trabajar, y esa distinción es la que separa esta etapa de una discusión de sobremesa."},{"q":"6. Los cinco textos citan a Titmuss (1970) y ninguno lo deja solo. Explica por qué, y qué principio de la casa se está aplicando.","guia":"Porque su tesis tiene una contracrítica obligada y una disputa empírica encima, y ocultarlas sería exactamente el vicio que esta materia enseña a cazar. Titmuss sostuvo que pagar por sangre reducía y empeoraba la donación; Kenneth Arrow le objetó en 1972 que de sus datos no se seguía esa conclusión moral; y en 2013, Lacetera, Macis y Slonim publicaron en «Science» experimentos de campo donde los incentivos sí aumentaron la donación. El principio que se aplica es el mismo que la etapa anterior usó con Coase y su rectificación de 1988: media cita es media cita. Y aquí aprieta más, porque la mitad que se estaría ocultando es la que le conviene a la conclusión bonita de la propia casa, que simpatiza con la idea de que hay límites. Una regla que solo se cumple cuando el resultado gusta no es una regla, es una preferencia con disfraz. Por eso el dato de 2013 entra en el mismo tamaño de letra que el de 1970, y por eso los cinco textos lo llevan adentro."},{"q":"7. El ensayo dice que las salidas son cuatro y no dos. Enumera las cuatro, explica cuál es la que casi nadie propone y por qué.","guia":"Las cuatro son: permitir, cuando ninguna objeción se sostiene; permitir con reglas, cuando la objeción es de justicia y se puede atacar la urgencia, la información o el daño; sacar el dinero y diseñar otro mecanismo; y prohibir, cuando el daño a la sociedad es grave y no hay diseño mejor. La que casi nadie propone es la tercera, y la razón es que exige trabajo en lugar de postura. Vender y prohibir son botones: se aprietan en una discusión de tres minutos y cada uno tiene su público. Diseñar obliga a averiguar dónde estaba el problema de verdad, que casi nunca es el precio. Alvin Roth lo mostró con los riñones: el problema no era cuánto se pagaba, era que había parejas de donante y paciente incompatibles entre sí y compatibles cruzadas, de modo que la solución era de emparejamiento y funciona sin dinero. Le dieron el Nobel en 2012, junto a Lloyd Shapley. En el caso de la fila del centro de salud, la salida de diseño son las citas por teléfono, que quitan valor al madrugón y por lo tanto al turno vendido. Y como toda salida, se escribe con su factura: montar y sostener ese sistema cuesta, y alguien lo paga."},{"q":"8. El cuento termina con una entrada que contradice al propio catálogo, y el narrador decide dejarla. Explica esa decisión y relaciónala con la regla del acero.","guia":"La entrada es la tesis de Brennan y Jaworski, de «Markets Without Limits», de 2015: si algo puede regalarse, también puede venderse, y lo reprobable, cuando lo hay, está en el acto y no en el pago. El narrador reconoce que no ha podido refutarla del todo y decide que esa incapacidad forma parte del catálogo en vez de invalidarlo. La decisión es la regla del acero llevada al extremo honesto: la tesis contraria entra en su mejor versión, no en una caricatura, y se deja escrita aunque incomode. Y hay algo más fino en la frase con que el cuento cierra, porque es la respuesta que el narrador sí puede dar: la pregunta nunca fue si algo puede venderse, sino qué queda de ese algo después de la venta. Es decir, concede el punto del adversario en el plano de lo posible y desplaza la discusión al plano donde su objeción sí funciona, que es el de la naturaleza del bien. Un catálogo que borrara la entrada incómoda no sería un catálogo, sería un alegato, y esa distinción es la que la casa persigue en todas las materias."},{"q":"9. Explica por qué esta etapa se sostiene sobre la etapa anterior y sobre la primera, y qué pasaría si alguien la leyera sola.","guia":"La etapa 1 puso el acero con cifras: la salida masiva de la pobreza es real y está medida, y sin eso cualquier crítica al mercado se lee como panfleto. La etapa 2 auditó la máquina por dentro y encontró cuatro fallas con nombre, todas firmadas por economistas y varias con Nobel, de modo que quedó claro que criticar no es estar del otro estante. Esta etapa hace la pregunta que ninguna de las dos podía hacer: qué pasa con los bienes donde el mercado funciona perfectamente y aun así uno no quiere que entre. Quien la leyera sola sacaría la conclusión que la etapa entera intenta evitar, que es «todo lo que se vende se corrompe», porque no tendría delante ni el acero de la etapa 1 ni la disciplina de la 2, que exige nombrar, proponer y calcular. Y al revés: quien se quedara en la 1 tendría una máquina sin condiciones de uso, y quien se quedara en la 2 tendría un diagnóstico técnico sin la pregunta moral. El arco tiene siete etapas y está declarado desde el principio precisamente para que nadie salga con media idea."},{"q":"10. Los cinco textos llevan la etiqueta de ejercicio de estilo de la casa. Explica por qué esa etiqueta pertenece al temario de esta etapa en particular, y qué pasaría si se quitara.","guia":"Porque esta etapa se estudia entera sobre qué pasa cuando se le pone precio a algo cuyo valor dependía de otra cosa, y el prestigio de un autor es justamente uno de esos bienes. Un pastiche sin declarar toma prestada la autoridad de Borges, de Cervantes o de Harari para que el texto pese más de lo que pesa por sí mismo, y eso es cobrar con una moneda que no se ganó. Enseñar que la disculpa comprada ya no es una disculpa, y firmar en la misma página con un nombre que no es el propio, sería la contradicción más rápida posible. Hay además una razón de método: la etiqueta funciona como el remedio que la etapa anterior estudió para la asimetría de información, y como todo remedio tiene un costo, que aquí es quitarle al texto parte de su prestigio prestado. Que la casa pague ese costo por escrito es la prueba práctica de que entendió la lección. Si se quitara pasarían dos cosas comprobables: alguien citaría a Sandel, a Satz o a Roth a través de una frase que ninguno escribió, y la casa quedaría produciendo la fuente inflada que su propio compendio manda cazar, justo en la materia donde más caro se paga hacerlo."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

/* ---------- III. Análisis complejo ---------- */
let laIdx=0,laPautaVisible=false;
function showLectA(){const cont=document.getElementById('laQ');if(!cont)return;const d=lectAnalisisBank[laIdx];document.getElementById('laProg').textContent='Pregunta '+(laIdx+1)+' de '+lectAnalisisBank.length;cont.textContent=d.q;const p=document.getElementById('laPauta');p.innerHTML='<strong>Pauta:</strong> '+d.guia;p.style.display=laPautaVisible?'block':'none';document.getElementById('laTA').value='';}
function nextLectA(){sfx('click');laIdx=(laIdx+1)%lectAnalisisBank.length;showLectA();}
function prevLectA(){sfx('click');laIdx=(laIdx-1+lectAnalisisBank.length)%lectAnalisisBank.length;showLectA();}
function toggleLectAPauta(){sfx('click');laPautaVisible=!laPautaVisible;const p=document.getElementById('laPauta');p.style.display=laPautaVisible?'block':'none';const b=document.getElementById('btnLectAPauta');if(b)b.textContent=laPautaVisible?'🙈 Ocultar pauta':'👁 Ver pauta';}

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso: una hoja
// suelta con un pastiche sin declarar es exactamente la fuente inflada que
// el Estudio Mayor enseña a cazar.
const LECTURAS_IMPR={
  borges:{titulo:'El catálogo de las cosas invendibles',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'De los azotes que se pusieron a precio, y de lo que sobre las cosas que el dinero estropea platicaron caballero y escudero',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'La especie que le puso precio a casi todo',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'Cuantas más cosas están en venta, más cuesta ser pobre',tipo:'Entrevista imaginada con Michael Sandel, a la manera de Ima Sanchís'},
  gala:{titulo:'Las cosas que no estaban en venta',tipo:'Conversación imaginada: Jesús Quintero con Antonio Gala'},
};
// Las dos entrevistas cambian de etiqueta impresa a propósito: no basta con
// declarar el pastiche, hay que decir con todas las letras que el ENCUENTRO
// NUNCA OCURRIÓ, porque una entrevista fotocopiada sin esa línea circula
// como si fuera una entrevista de verdad, y eso es una cita apócrifa entera.
const LECTURAS_ETIQ={
  entrevista:`<div class="etiqueta"><strong>⚠️ Entrevista imaginada: el encuentro nunca ocurrió.</strong> Michael Sandel (Minneapolis, 1953) está vivo y no ha dicho estas palabras: la conversación la escribió el Proyecto Educativo F.A.R.O. a la manera de Ima Sanchís, como ejercicio de estilo declarado y en homenaje. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro del texto es real y comprobable</strong>; lo único inventado es la conversación.</div>`,
  gala:`<div class="etiqueta"><strong>⚠️ Conversación imaginada: el encuentro nunca ocurrió.</strong> Jesús Quintero (1940-2022) y Antonio Gala (1930-2023) se entrevistaron de verdad varias veces, pero esta charla la escribió el Proyecto Educativo F.A.R.O. imitando sus voces, como ejercicio de estilo declarado y en homenaje. <strong>Toda obra, fecha y cifra citada dentro del texto es real y comprobable</strong>; lo único inventado es la conversación.</div>`,
};
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · Lo que el dinero no debe comprar · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#2e1065;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#4c1d95;border-bottom:1.5pt solid #4c1d95;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #4c1d95;background:#f5f3ff;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#2e1065;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#4c1d95;background:#f5f3ff;border-left:3pt solid #4c1d95;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#4c1d95;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🩸 Lo que el dinero no debe comprar${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🩸 Ruta del Expediente Dorado · Etapa 3 de 7</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +(LECTURAS_ETIQ[clave]||`<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>`)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  _abreImpresion(_hojaImpresa(meta.titulo,cuerpo+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🩸 Ruta del Expediente Dorado · Etapa 3 de 7</span><span>Las cinco lecturas 📖</span></div>`
    +`<h1>Las cinco lecturas de «Lo que el dinero no debe comprar»</h1><div class="tipo">Un cuento, un capítulo de caballerías, un ensayo, una entrevista y una conversación, sobre el mismo límite</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco textos <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, ni de Ima Sanchís, Michael Sandel, Jesús Quintero o Antonio Gala: los escribió el Proyecto Educativo F.A.R.O. imitando sus voces, y se declaran como pastiche. Las dos entrevistas son <strong>encuentros que nunca ocurrieron</strong>: las personas son reales y lo inventado es la conversación. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las cinco lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las cinco lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🩸 Ruta del Expediente Dorado · Etapa 3 de 7</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las cinco lecturas</h1><div class="tipo">Lo que el dinero no debe comprar · 25 de comprensión lectora, 10 de completar y 10 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los cinco textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco textos son <strong>ejercicios de estilo de la casa, no obra de Borges, Cervantes ni Harari</strong>, y las dos entrevistas son encuentros que <strong>nunca ocurrieron</strong>.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (25 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (10 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (10 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue llenando la hoja del bien!','¡Muy buen trabajo!','¡Aprendiz de criterio!','¡Ya distingues la justicia de la corrupción!','¡Muestras la pérdida y pagas la factura!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🩸 ¡'+name+' completó la Etapa 3 de la Ruta del Expediente Dorado (Lo que el dinero no debe comprar)! 🏅 Progreso: '+pct+'% · 🩸 policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

